// The ghost hint (design: "Retry and help"): after Help.hintDeaths deaths in a room, a ghost replays
// that room's recorded solution once. The recordings are the bot solutions from tests/stagebots.ts,
// stored as run-length-encoded tick inputs in ghosts.ts (regenerated by tests/ghosts.test.ts). The
// sim is deterministic, so replaying a recording from a fresh copy of the room retraces it exactly.

import { BUTTONS, TickInput, noButtons } from './input';
import { GHOSTS } from './ghosts';

/** One tick's input as a number: the low bits held, the next BUTTONS.length bits pressed (in BUTTONS order). */
export function inputMask(inp: TickInput): number {
  let m = 0;
  BUTTONS.forEach((b, i) => {
    if (inp.held[b]) m |= 1 << i;
    if (inp.press[b]) m |= 1 << (i + BUTTONS.length);
  });
  return m;
}

export function maskInput(m: number): TickInput {
  const held = noButtons();
  const press = noButtons();
  BUTTONS.forEach((b, i) => {
    held[b] = (m & (1 << i)) !== 0;
    press[b] = (m & (1 << (i + BUTTONS.length))) !== 0;
  });
  return { held, press };
}

/** Run-length encoding: "mask.count" pairs in base 36, comma separated. */
export function encodeInputs(inputs: TickInput[]): string {
  const out: string[] = [];
  let last = -1;
  let n = 0;
  for (const inp of inputs) {
    const m = inputMask(inp);
    if (m === last) { n++; continue; }
    if (n) out.push(`${last.toString(36)}.${n.toString(36)}`);
    last = m;
    n = 1;
  }
  if (n) out.push(`${last.toString(36)}.${n.toString(36)}`);
  return out.join(',');
}

export function decodeInputs(s: string): TickInput[] {
  const out: TickInput[] = [];
  if (!s) return out;
  for (const tok of s.split(',')) {
    const [m, n] = tok.split('.').map((v) => parseInt(v, 36));
    for (let i = 0; i < n; i++) out.push(maskInput(m));
  }
  return out;
}

/** The recorded route through a room, or null if it has none. */
export function ghostInputs(roomId: string): TickInput[] | null {
  const s = GHOSTS[roomId];
  return s ? decodeInputs(s) : null;
}
